 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc, color))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append(cells)
    return comps


def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = _components(grid)
    positions = [set((r, c) for r, c, _ in comp) for comp in comps]
    # Repeatedly slide each object one cell right whenever it is clear.
    # Objects only move right; their original left-to-right order is preserved.
    while True:
        occupied = set().union(*positions) if positions else set()
        moves = []
        for i, cells in enumerate(positions):
            shifted = {(r, c + 1) for r, c in cells}
            if any(c >= w for _, c in shifted):
                continue
            other = occupied - cells
            if shifted.isdisjoint(other):
                moves.append((i, shifted))
        if not moves:
            break
        # Update together to avoid traversal-order bias.
        for i, shifted in moves:
            positions[i] = shifted
    out = [[0] * w for _ in range(h)]
    for comp, cells in zip(comps, positions):
        color = comp[0][2]
        for r, c in cells:
            out[r][c] = color
    return out
